"""Work with us: brand-specific pages with one existing email enquiry route."""
from html import escape

ROOT = '/work-with-us/'


def action(label, href, secondary=False):
    return f'<a class="btn {"ww-secondary" if secondary else "btn-dark"}" href="{escape(href, quote=True)}">{escape(label)} →</a>'


def enquiry(role):
    return ROOT + 'enquire/?role=' + role


def panel(title, text, cta, href, number=''):
    return f'<article class="ww-card"><p class="eyebrow">{number}</p><h2>{title}</h2><p>{text}</p>{action(cta, href)}</article>'


def render_partnership_page(brand, route, page, hero, photo, events, boom_base, pm_base):
    pm = brand == 'pm'
    name = 'THE 2PM CLUB Daytime Disco' if pm else 'Boombastic Events'
    hero_caption = ('THE 2PM CLUB, Leicester, May 2026' if route == 'venues' else 'THE 2PM CLUB, Northampton, June 2026') if pm else 'Boombastic 90s, Northampton, September 2026'
    recruitment = boom_base + '/jobs/' if pm else '/jobs/'
    assets = '<link rel="stylesheet" href="/assets/partnerships.css">'
    back = '<p class="ww-back"><a href="/work-with-us/">← Work with us</a></p>'
    if route == 'index':
        intro = ('Bring the daytime dancefloor to your venue. Join the team. Or help us capture the afternoons people talk about.' if pm else
                 'Bring a Boombastic party to your venue. Join the event team. Or help us capture the moments and reach more local people.')
        h = hero(brand, 'WORK WITH US.', intro, action('Become a venue partner', ROOT + 'venues/'), 'pm-arms.jpg' if pm else 'b90-stage.jpg', eyebrow=name, cap=hero_caption, cls='ww-hero')
        cards = panel('VENUES', 'A regular local party, planned around your programme. Let’s talk about your room, your audience and the dates that could work.', 'Explore venue partnerships', ROOT + 'venues/', 'A place to come back to')
        cards += panel('DJs & EVENT CREW', 'Paid event work with Boombastic Events and THE 2PM CLUB. Our current DJ and Event Assistant roles explain the work and practical requirements.', 'View paid event roles', recruitment, 'The people behind the party')
        cards += panel('CONTENT CREATORS', 'Photographers, videographers and local promoters. Tell us what you make, or who you reach, and the kind of collaboration you have in mind.', 'Explore creator collaborations', ROOT + 'content-creators/', 'Capture it. Share it.')
        body = assets + h + '<section class="section container"><div class="ww-grid ww-three">' + cards + '</div></section>'
        body += f'<section class="ww-band"><div class="container"><h2>LET’S START WITH A CONVERSATION.</h2><p>A venue, a skill or a local audience. Tell us where you are and how you would like to work with {name}.</p>{action("Make an enquiry", enquiry("venue"))}</div></section>'
        return page(brand, 'Work with us', body, f'Venue partnerships, paid event roles and content creator collaborations with {name}.', active=ROOT, sticky_label='Work with us', sticky_href='#main', body_class='is-partnership')

    if route == 'venues':
        sub = ('Sing Out Loud Anthems from the 80s, 90s and 00s. Friends together. A daytime party your town can put back in the diary.' if pm else
               'Big choruses, familiar faces and a reason to get everyone together. Let’s find the Boombastic format that fits your venue.')
        title = 'YOUR VENUE.\nTHEIR NEXT AFTERNOON.' if pm else 'YOUR VENUE.\nOUR NEXT PARTY.'
        h = hero(brand, title.replace('\n', '<br>'), sub, action('Tell us about your venue', enquiry('venue')), 'pm-leic.jpg' if pm else 'b90-stage.jpg', eyebrow='Venue partnerships · ' + name, cap=hero_caption, cls='ww-hero', h1cls='h1-long')
        story = ('<p>THE 2PM CLUB Daytime Disco brings the songs people sing in the car onto a proper dancefloor. Whitney, Wham!, Spice Girls, Oasis and Beyoncé. Friends with their arms around each other, already talking about the next one.</p><p>We want to build regular afternoons with venues that understand their local crowd. The aim is roughly three or four dates a year in each suitable venue, giving people something familiar to return to and bring their friends along to.</p>' if pm else
                 '<p>Boombastic Events brings people together around the songs they know. A daytime singalong, a whole decade on the dancefloor, or three DJs and three channels at a silent disco. The format starts with your room and the people who could make it their regular plan.</p><p>We are looking for a small network of local venue partners. The aim is roughly three or four events a year in each suitable venue, with time between dates to build a community that comes back.</p>')
        story += '<p>We work around your existing programme. If soul, rock or trance nights already have their place, a mixed decades party can give your calendar another kind of gathering. We will talk through the fit together.</p>'
        body = assets + h + f'<section class="section container ww-split"><div>{back}<p class="eyebrow">A regular relationship</p><h2>A DATE WORTH COMING BACK FOR.</h2>{story}</div><div>{photo("pm-friends.jpeg" if pm else "b90-group.jpg", "ww-photo")}</div></section>'
        brings = panel('THE PARTY', 'An established event format, a clear music brief and DJs who know how to bring the room into the chorus.', 'See the experience', '/what-to-expect/' if pm else '/about/#parties', '01')
        brings += panel('THE INVITATION', 'Our owned event pages and ticket journey, event artwork and marketing activity. We agree how we and the venue will help local people hear about each date.', 'See current events', '/events/' if pm else '/whats-on/', '02')
        brings += panel('THE PLAN', 'A conversation about sound, equipment, access, staffing, setup and timings. Responsibilities and commercial arrangements are agreed for each venue.', 'Start the conversation', enquiry('venue'), '03')
        body += '<section class="ww-tint"><div class="section container"><div class="sec-head"><h2>WHAT WE BRING.</h2></div><div class="ww-grid ww-three">' + brings + '</div></div></section>'
        if not pm:
            formats = [('THE 2PM CLUB Daytime Disco', 'Sing Out Loud Anthems from the 80s, 90s and 00s, in the afternoon.', pm_base + '/what-to-expect/'), ('Boombastic 90s', 'Pop, Britpop, dance and hip-hop. All of the nineties.', '/boombastic-90s/'), ('Footloose 80s', 'Big 80s anthems and classic videos above the dancefloor.', '/footloose-80s/'), ('Silent Disco Greatest Hits', 'Three live DJs. Three headphone channels. Pop, indie and dance.', '/silent-disco/'), ('Family Silent Disco', 'A dancefloor for children and their grown-ups, with three music channels.', '/family-silent-disco/')]
            body += '<section class="section container"><p class="eyebrow">Find the fit</p><h2>DIFFERENT PARTIES. THE SAME WARM WELCOME.</h2><div class="ww-format-list">' + ''.join(f'<a href="{url}"><strong>{label}</strong><span>{text}</span><span aria-hidden="true">→</span></a>' for label,text,url in formats) + '</div></section>'
        clip = 'https://boombastic-events.b-cdn.net/web%20hero/hero-1x1.mp4'
        proof = f'<figure class="ww-film"><video controls playsinline preload="none" poster="/assets/pm-wide.jpg" aria-label="Footage from previous THE 2PM CLUB events"><source src="{clip}" type="video/mp4"></video><figcaption>Footage from previous THE 2PM CLUB events</figcaption></figure>'
        own = [e for e in events if e['brand'] == brand][:2]
        examples = ''.join(f'<a class="ww-example" href="{escape(e["path"])}"><span>{escape(e["city"])} · {escape(e["venue"])}</span><strong>{escape(e["title"])}</strong><span>View the event →</span></a>' for e in own)
        body += f'<section class="section container ww-split ww-proof"><div><p class="eyebrow">The room tells the story</p><h2>{"YOUR BEST NIGHT OUT.<br>IN THE MIDDLE OF THE AFTERNOON." if pm else "SEE THE PARTY FOR YOURSELF."}</h2><p>{"Real afternoons, real friends and the songs the whole room knows." if pm else "Our event photos and daytime disco footage show the people and the atmosphere behind the formats."}</p><div class="ww-examples">{examples}</div></div>{proof}</section>'
        steps = '<ol class="ww-steps"><li><h3>TELL US ABOUT THE ROOM.</h3><p>Send the venue, town, usable event capacity, current programme and potential date windows.</p></li><li><h3>TALK THROUGH THE FIT.</h3><p>We discuss the audience, event format, practical setup and how a first date could work. A visit may be the next useful step.</p></li><li><h3>AGREE THE DETAILS.</h3><p>Dates, hire or ticket arrangements, venue responsibilities and marketing are agreed individually before a booking is confirmed.</p></li></ol>'
        body += '<section class="ww-tint"><div class="section container"><h2>HOW WE GET STARTED.</h2>' + steps + '</div></section>'
        body += '<section class="ww-band"><div class="container"><h2>LET’S TALK ABOUT YOUR VENUE.</h2><p>You do not need a finished proposal. A few practical details give us a useful place to start.</p>' + action('Make a venue enquiry', enquiry('venue')) + '</div></section>'
        return page(brand, 'Venue partnerships', body, f'Bring {name} to your venue. Explore a regular local partnership, event formats and an initial conversation.', active=ROOT, sticky_label='Make a venue enquiry', sticky_href=enquiry('venue'), body_class='is-partnership')

    if route == 'content-creators':
        h = hero(brand, 'THE CHORUS.\nTHE CROWD.\nYOUR EYE.'.replace('\n','<br>'), 'Good photos. Video that puts you in the room. Local voices that help the next group of friends find us.', action('Tell us what you do', enquiry('creator')), 'pm-mic.jpg' if pm else 'b90-mic.jpg', eyebrow='Content creators · ' + name, cap=hero_caption, cls='ww-hero')
        capture = panel('MAKE PHOTOS & VIDEO', 'Catch the arms in the air, the chorus and the friends who finally got a date in the diary. Show us your photography, event films or short social clips. Your portfolio matters; a large following is not a requirement.', 'Enquire about photo or video work', enquiry('creator'), 'Capture the party')
        promotion = panel('REACH LOCAL PEOPLE', 'If your audience follows you for things to do locally, tell us where they are, what you share and how a collaboration could work. Include recent reach or audience information that helps us understand the fit.', 'Enquire about local promotion', enquiry('promotion'), 'Help people find us')
        body = assets + h + '<section class="section container">' + back + '<div class="ww-grid ww-two">' + capture + promotion + '</div></section>'
        body += f'<section class="section container ww-split"><div>{photo("pm-hug.jpg" if pm else "b90-crowd.jpg", "ww-photo")}</div><div><p class="eyebrow">Your work. Your terms.</p><h2>SHOW US WHAT YOU DO.</h2><p>Tell us where you are based, how far you can travel and which kind of collaboration you offer. Send portfolio or social links, your availability and your rates or proposed commercial approach.</p><p>We will talk through the brief, event dates, deliverables, content usage and payment arrangements before agreeing any work.</p><p>If you both make content and promote it to an audience, tell us about both. We will only ask for audience reach when promotion is part of your proposal.</p>{action("Make a creator enquiry", enquiry("creator"))}</div></section>'
        return page(brand, 'Content creators', body, f'Photography, video and local audience collaborations with {name}. Share your portfolio, availability and rates.', active=ROOT, sticky_label='Make a creator enquiry', sticky_href=enquiry('creator'), body_class='is-partnership')

    body = assets + '<script src="/assets/partnerships.js" defer></script>'
    body += f'<section class="page-band"><div class="container"><p class="eyebrow">Work with us · {name}</p><h1>LET’S TALK.</h1><p>Share a few details. We’ll prepare an email for you to review and send to the team.</p></div></section><section class="section container ww-enquiry">{back}'
    body += f'''<div class="ww-form-layout"><form id="ww-enquiry" data-default-brand="{brand}"><div class="ww-fields">
<label>Brand<select name="brand"><option value="boom" {'selected' if not pm else ''}>Boombastic Events</option><option value="pm" {'selected' if pm else ''}>THE 2PM CLUB Daytime Disco</option></select></label>
<label>What would you like to discuss?<select name="role"><option value="venue">Venue partnership</option><option value="creator">Photography or video</option><option value="promotion">Local audience promotion</option><option value="both">Content creation and audience promotion</option><option value="dj">DJ work</option><option value="event-assistant">Event Assistant work</option></select></label>
<label>Your name<input name="name" autocomplete="name" required maxlength="100"></label><label>Email<input type="email" name="email" autocomplete="email" required maxlength="160"></label>
<label>Town / location<input name="location" autocomplete="address-level2" required maxlength="160"></label><label>Phone (optional)<input type="tel" name="phone" autocomplete="tel" maxlength="40"></label>
</div>
<fieldset data-roles="venue"><legend>About your venue</legend><div class="ww-fields"><label>Venue name<input name="venue" required maxlength="160"></label><label>Venue website (optional)<input type="url" name="venue_url" placeholder="https://" maxlength="300"></label><label>Usable event capacity<input name="capacity" required maxlength="120" placeholder="Dancefloor capacity, or your best estimate"></label><label>Your role at the venue (optional)<input name="venue_contact_role" maxlength="100"></label><label class="ww-wide">Existing programme<textarea name="programme" required maxlength="1200" rows="3" placeholder="Regular events and the people they bring in"></textarea></label><label class="ww-wide">Potential date windows<textarea name="dates" required maxlength="700" rows="3" placeholder="Days, months or gaps you would like to discuss"></textarea></label></div></fieldset>
<fieldset data-roles="creator promotion both"><legend>Your collaboration</legend><div class="ww-fields"><label>Travel range<input name="travel" required maxlength="160" placeholder="Towns or distance you can cover"></label><label>Portfolio / social links<textarea name="links" required maxlength="800" rows="3" placeholder="Website, showreel or relevant profiles"></textarea></label><label class="ww-wide">What do you offer?<textarea name="collaboration" required maxlength="1000" rows="3" placeholder="Photography, event film, short clips, local promotion…"></textarea></label><label>Availability<input name="availability" required maxlength="250" placeholder="Typical days, dates or notice needed"></label><label>Rates / proposed commercial approach<textarea name="rates" required maxlength="700" rows="3" placeholder="Your rates, or how you would like to discuss a brief"></textarea></label></div></fieldset>
<fieldset data-roles="promotion both"><legend>Your audience</legend><div class="ww-fields"><label>Audience locations<input name="audience_location" required maxlength="300" placeholder="Main towns / areas"></label><label>Audience size and recent reach<textarea name="reach" required maxlength="700" rows="3" placeholder="Relevant followers, views or reach, with the period covered"></textarea></label></div></fieldset>
<fieldset data-roles="dj event-assistant"><legend>Event work</legend><p id="ww-role-link"></p><div class="ww-fields"><label class="ww-wide">Experience and links<textarea name="experience" required maxlength="1200" rows="4" placeholder="Tell us about relevant experience. Event Assistants do not need previous event experience."></textarea></label><label>General availability<input name="work_availability" required maxlength="250"></label><label>Travel / vehicle<input name="work_travel" required maxlength="350" placeholder="How you would get to events; DJs need a large car or van for kit from NN7"></label></div></fieldset>
<label class="ww-wide ww-note">Anything else? (optional)<textarea name="message" maxlength="1200" rows="4" placeholder="Practical details, questions or what you have in mind"></textarea></label>
<p class="fine">These details are used to handle your enquiry. <a href="/privacy/">Read our privacy policy</a>.</p><button class="btn btn-dark" type="submit">Prepare enquiry email →</button><p class="ww-status" id="ww-status" role="status" aria-live="polite"></p>
</form><aside class="ww-form-help"><h2>ONE TEAM. ONE INBOX.</h2><p>Your enquiry goes to <a href="mailto:hello@boomevents.co.uk">hello@boomevents.co.uk</a>, with the brand and enquiry type in the subject.</p><p>This form prepares your message. You review it and send it from your email app. You can also copy the details into webmail.</p><p>Prefer to write directly? Email the team with the brand, what you would like to discuss and your contact details.</p></aside></div>
<section id="ww-prepared" class="ww-prepared" hidden aria-labelledby="ww-review-title"><h2 id="ww-review-title" tabindex="-1">YOUR ENQUIRY EMAIL.</h2><p>Review the details below, then open your email app or copy them into a message to <strong>hello@boomevents.co.uk</strong>.</p><label>Subject<input id="ww-subject" readonly></label><label>Message<textarea id="ww-email-body" readonly rows="14"></textarea></label><div class="ww-actions"><a id="ww-open-email" class="btn btn-dark" href="mailto:hello@boomevents.co.uk">Open email app →</a><button id="ww-copy-email" class="btn ww-secondary" type="button">Copy email details</button></div><p class="fine">Nothing has been sent by this website. Send your message from your email app to complete the enquiry.</p></section>
<noscript><p>Email <a href="mailto:hello@boomevents.co.uk">hello@boomevents.co.uk</a> with the brand, enquiry type and the details listed above. The guided email preparation needs JavaScript.</p></noscript></section>'''
    return page(brand, 'Work with us enquiry', body, f'Prepare a venue, creator or paid event work enquiry for {name}.', active=ROOT, body_class='is-partnership is-enquiry')
